import {api,get,post,put} from '../api.js';
import {e,formatMoney,formatDate,state,blank,notify,copy,safeExternal,formValues,title} from '../lib.js';
const labels={inactive:'غير مفعّلة',trial_pending:'التجربة بانتظار الموافقة',trial_active:'تجربة مجانية نشطة',trial_expired:'انتهت التجربة',active:'نشطة',grace:'فترة سماح',credit:'آجل',suspended:'موقوفة',cancelled:'ملغاة'};
const payStatus={pending_admin:'بانتظار المراجعة',approved:'مقبول',rejected:'مرفوض'};
const sections=[['overview','نظرة عامة','◈'],['plans','الباقات والطلبات','◫'],['billing','الفواتير والدفع','▤'],['trial','التجربة المجانية','✧'],['router','التحقق من MikroTik','⌘'],['access','الاتصال والوصول','↗'],['devices','لوحة الأجهزة','⊞'],['settings','الحساب والأمان','⚙']];
const A={data:null,config:null,plans:[],ports:null,tab:'overview',script:'',verifyScript:'',loading:true,error:'',message:'',busy:''};
export async function openAccount(){title('لوحة المشترك');const root=document.getElementById('account-root');if(!root)return;root.innerHTML=`<div class="dashboard-loader" role="status"><span class="loading-spin"></span>جارٍ جلب معلومات الحساب من الخدمة...</div>`;if(!A.data){await refreshAccount(true)}else renderAccount()}
async function refreshAccount(first=false){A.loading=true; if(!first)A.error='';try{const me=await get('/me');A.data=me;state.me=me;state.meChecked=true;const headerLink=document.querySelector('.head-cta .login-link');if(headerLink){headerLink.href='/account';headerLink.textContent='لوحة التحكم'}const [cfg,pl]=await Promise.allSettled([get('/config'),get('/plans')]);A.config=cfg.status==='fulfilled'?cfg.value:null;A.plans=pl.status==='fulfilled'?(Array.isArray(pl.value)?pl.value:pl.value?.plans||[]):[];
 if(me?.router?.provisioned){try{A.ports=await get('/router/connection-ports')}catch{A.ports=null}}else A.ports=null;
 if(cfg.status==='rejected'||pl.status==='rejected'){A.message='بعض بيانات الباقات أو إعدادات الدفع غير متاحة الآن؛ يمكن تحديث الصفحة لاحقًا.'}
 }catch(err){if(err.status===401){A.data=null;state.me=null;state.meChecked=true;history.replaceState({},'','/customer-login');document.dispatchEvent(new CustomEvent('onstar:navigate',{detail:'/customer-login'}));return}A.error=err.message}finally{A.loading=false;renderAccount()}}
const statusText=s=>labels[s]||s||'غير محددة';
function statusPill(s){return `<span class="status ${['active','trial_active','grace','approved','credit'].includes(s)?'positive':['suspended','rejected','cancelled'].includes(s)?'negative':''}"><span class="status-led"></span>${e(statusText(s))}</span>`}
function accountView(){const d=A.data;if(!d){return `<section class="dashboard-failure"><h1>تعذر تحميل حسابك</h1><p>${e(A.error||'لم تتوفر معلومات الحساب.')}</p><button class="button primary" data-action="refresh">إعادة المحاولة</button></section>`}
const c=d.customer||{};return `<div class="dash-frame"><aside class="dash-side"><div class="dash-side-header"><small>ONSTAR CLOUD</small><h2>منطقة المشترك</h2><div class="dash-identity"><div class="avatar">${e((c.network_name||c.full_name||'O').slice(0,1))}</div><div><strong>${e(c.network_name||c.full_name||'المشترك')}</strong><span dir="ltr">${e(c.email)}</span></div></div></div><nav class="dash-nav" aria-label="أقسام حسابك">${sections.map(([id,name,ico])=>`<button type="button" class="${A.tab===id?'active':''}" data-tab="${id}"><span aria-hidden="true">${ico}</span>${name}<span class="dash-nav-arrow">↖</span></button>`).join('')}</nav><div class="dash-side-bottom"><span class="status-led"></span>الحالة: ${e(statusText(d.service?.status))}</div></aside><section class="dash-body"><div class="dash-topbar"><div><span class="eyebrow">ACCOUNT / ${e(A.tab.toUpperCase())}</span><h1>${e(sections.find(s=>s[0]===A.tab)?.[1])}</h1></div><div class="dash-actions"><button class="small-button" data-action="refresh" ${A.busy?'disabled':''}>↻ تحديث</button><button class="small-button muted" data-action="logout">خروج ↗</button></div></div>${A.error?`<div class="dashboard-alert error" role="alert">${e(A.error)}</div>`:''}${A.message?`<div class="dashboard-alert success" role="status">${e(A.message)}</div>`:''}${!c.email_verified?`<div class="dashboard-alert verify"><div><b>يرجى تأكيد بريدك الإلكتروني</b><p>قبل طلب التجربة أو استكمال الاشتراك.</p></div><div class="button-row"><a data-link href="/verify-email?email=${encodeURIComponent(c.email||'')}" class="button primary">تأكيد البريد</a><button class="button dark-outline" data-action="resend">إرسال رمز جديد</button></div></div>`:''}<div class="dash-content">${dashboardTab()}</div></section></div>`}
function dashboardTab(){const d=A.data||{},c=d.customer||{},router=d.router||{},s=d.service||{},f=d.financial||{},sub=d.subscription||{},trial=d.trial||{}; const verified=!!c.email_verified;switch(A.tab){
case 'overview':return `<div class="welcome-panel"><div><span class="eyebrow">YOUR NETWORK / LIVE ACCOUNT</span><h2>مرحبًا، ${e(c.full_name||'بك')}</h2><p>بياناتك الفعلية كما يعرضها السيرفر. احصل على التفاصيل من قائمة الأقسام.</p></div>${statusPill(s.status)}</div><div class="metric-grid"><div class="metric"><span>حالة الخدمة</span><strong>${e(statusText(s.status))}</strong><small>${s.suspend_at?`موعد الإيقاف ${formatDate(s.suspend_at)}`:'حسب آخر بيانات الخدمة'}</small></div><div class="metric"><span>${f.status==='credit'?'رصيد دائن':'رصيد مستحق'}</span><strong>${formatMoney(f.status==='credit'?f.credit_balance:f.balance_due,f.currency||A.config?.payment?.currency||'')}</strong><small>${f.status==='credit'?'رصيد لصالحك':'المبلغ المسجل في حسابك'}</small></div><div class="metric"><span>التحقق من MikroTik</span><strong>${router.serial_verified?'تم التحقق':'بانتظار التحقق'}</strong><small>${e(router.model||'وفق بيانات الجهاز')}</small></div><div class="metric"><span>الوصول عن بُعد</span><strong>${router.provisioned?(router.remote_access_enabled?'متاح':'غير مفعّل'):'لم يتم التجهيز'}</strong><small>حسب حالة الخدمة والصلاحيات</small></div></div><div class="dash-panel"><div class="dash-panel-head"><h2>متابعة رحلتك</h2><span>الخطوات ذات الصلة بحسابك</span></div><div class="quick-links"><button data-tab="plans">اختيار الباقة <span>↗</span></button><button data-tab="router">التحقق من الراوتر <span>↗</span></button><button data-tab="access">عناوين الوصول <span>↗</span></button><button data-tab="billing">الدفع والفواتير <span>↗</span></button></div></div><div class="dash-two"><div class="dash-panel"><h2>الاشتراك الحالي</h2><div class="info-rows"><div><span>الباقة</span><b>${e(sub.plan_name||'غير محددة')}</b></div><div><span>الفترة</span><b>${formatDate(sub.paid_period_start)} — ${formatDate(sub.paid_period_end)}</b></div><div><span>حالة التجربة</span><b>${e(trial.status||'غير محددة')}</b></div></div></div><div class="dash-panel"><h2>لوحة الأجهزة</h2><p>يمكن الوصول إلى لوحة إدارة الأجهزة بعد تخصيصها لحسابك من الإدارة.</p>${router.device_portal?`<button class="button primary" data-tab="devices">عرض لوحة الأجهزة</button>`:blank('لم تُخصّص لوحة أجهزة بعد')}</div></div>`;
case 'plans':return `<div class="dash-intro"><h2>باقتك المناسبة، على بيانات فعلية.</h2><p>تُجلب الباقات مباشرةً من النظام. إنشاء الطلب يجهّز الفاتورة ولا يعني تفعيل الخدمة.</p></div><div class="plan-grid">${A.plans.length?A.plans.map(p=>`<article class="plan"><span class="eyebrow">SUBSCRIPTION</span><h3>${e(p.name)}</h3><div class="plan-price">${formatMoney(p.price,p.currency)}</div><p>${e(p.billing_months)} شهر · ${p.trial_allowed?'قد تكون التجربة متاحة':'بدون تجربة'}</p><button class="button primary" data-action="order" data-id="${e(p.id)}" ${(d.orders||[]).some(o=>['pending_payment','pending_admin'].includes(o.status))||!!sub.plan_name||!verified||A.busy?'disabled':''}>${sub.plan_name===p.name?'الباقة الحالية':(d.orders||[]).some(o=>['pending_payment','pending_admin'].includes(o.status))?'يوجد طلب مفتوح':'إنشاء الطلب والفاتورة'}</button></article>`).join(''):blank('لا توجد باقات متاحة','تعذّر جلب الباقات أو لا توجد باقات منشورة حاليًا.')}</div><div class="dash-panel"><h2>الطلبات الحالية</h2>${itemRows(d.orders||[],x=>`<b>${e(x.plan_name||x.invoice_no||'طلب اشتراك')}</b><span>${e(x.status||'')}</span>`,`<span>طلبات الاشتراك</span>`)}</div>`;
case 'billing':return `<div class="dash-two"><div class="dash-panel"><h2>الفواتير</h2>${itemRows(d.invoices||[],x=>`<div><b>${e(x.invoice_no||'فاتورة')}</b><small>${e(x.status||'')}</small></div><div class="align-end"><strong>${formatMoney(x.balance_due,x.currency)}</strong><small>${formatDate(x.due_date)}</small></div>`)}</div><div class="dash-panel"><h2>تأكيدات الدفع</h2>${itemRows(d.payment_confirmations||[],x=>`<div><b>${e(x.transaction_number)}</b><small>${e(x.depositor_name)}</small></div><div class="align-end"><strong>${formatMoney(x.amount,x.currency)}</strong><small>${e(payStatus[x.status]||x.status)}</small></div>`)}</div></div><div class="dash-panel payment-layout"><div class="payment-sidebar"><span class="eyebrow">PAYMENT / REVIEW</span><h2>إرسال إثبات الدفع</h2><p>العملية تُرسل للمراجعة فقط، ولا تُعتبر دفعة معتمدة إلا بعد قبول الإدارة.</p>${A.config?.payment?`<div class="payment-target"><span>${e(A.config.payment.method||'وسيلة الدفع')}</span><b>${e(A.config.payment.account_label||'')}</b><strong dir="ltr">${e(A.config.payment.account_number||'')}</strong>${A.config.payment.account_number?`<button class="inline-action" data-copy="paymentAccount">نسخ رقم الحساب</button>`:''}</div>`:'<div class="dashboard-alert">تفاصيل الدفع غير متاحة حاليًا. لا تنفّذ تحويلًا اعتمادًا على معلومات غير مؤكدة.</div>'}</div><form id="payment-form" class="dash-form"><div class="form-grid">${(d.invoices||[]).some(x=>['pending','partial','credit','overdue'].includes(x.status))?`<label class="field wide"><span>الفاتورة</span><select name="invoice_id"><option value="">الأقدم تلقائيًا</option>${(d.invoices||[]).filter(x=>['pending','partial','credit','overdue'].includes(x.status)).map(x=>`<option value="${e(x.id)}">${e(x.invoice_no)} — ${formatMoney(x.balance_due,x.currency)}</option>`).join('')}</select></label>`:''}<label class="field"><span>اسم المودع</span><input name="depositor_name" required></label><label class="field"><span>رقم العملية</span><input name="transaction_number" required></label><label class="field"><span>المبلغ</span><input name="amount" inputmode="decimal" required></label><label class="field"><span>تاريخ الإيداع</span><input name="deposit_date" type="date" required></label><label class="field wide"><span>رسالة للإدارة (اختياري)</span><textarea name="message" rows="3"></textarea></label><label class="field wide"><span>صورة أو PDF للإيصال (اختياري)</span><input name="receipt" type="file" accept="image/*,.pdf,application/pdf"></label></div><button type="submit" class="button primary" ${A.busy?'disabled':''}>${A.busy==='payment'?'جارٍ الإرسال...':'إرسال للمراجعة'}</button></form></div>`;
case 'trial':return `<div class="dash-intro"><h2>تجربة مجانية، بموافقة الإدارة.</h2><p>لا يبدأ احتساب فترة التجربة عند الطلب؛ يبدأ بعد اعتماد الإدارة وتطبيق شروط الأهلية.</p></div><div class="dash-panel"><div class="dash-panel-head"><h2>الأهلية الحالية</h2>${statusPill(trial.status)}</div><div class="metric-grid compact"><div class="metric"><span>المدة الافتراضية</span><strong>${e(trial.default_days??'—')} أيام</strong></div><div class="metric"><span>نهاية التجربة</span><strong>${formatDate(trial.ends_at)}</strong></div><div class="metric"><span>إمكانية الطلب</span><strong>${trial.can_request?'مؤهل':'غير متاح حاليًا'}</strong></div></div>${trial.eligibility_reasons?.length?`<div class="dashboard-alert">${trial.eligibility_reasons.map(e).join(' · ')}</div>`:''}${trial.can_request&&verified?`<button class="button primary" data-action="trial" ${A.busy?'disabled':''}>طلب تجربة مجانية</button>`:`<p class="subdued">${trial.status==='pending_admin'?'طلبك بانتظار المراجعة.':'يحدد السيرفر أهلية الطلب حسب حسابك والتحقق من جهازك.'}</p>`}</div>`;
case 'router':return `<div class="dash-intro"><h2>ربط MikroTik بحسابك.</h2><p>الكود يُولَّد بواسطة السيرفر، والتحقق لا يكتمل إلا بعد قراءة حالة الجهاز من النظام.</p></div><div class="dash-panel"><div class="dash-panel-head"><h2>حالة التحقق</h2><span class="status ${router.serial_verified?'positive':''}">${router.serial_verified?'تم التحقق':'بانتظار التحقق'}</span></div><div class="info-rows"><div><span>الجهاز</span><b>${e(router.model||router.board_name||'لم يتم تحديده')}</b></div><div><span>حالة Serial</span><b>${router.serial_verified?'تم التحقق':'بانتظار التحقق'}</b></div>${router.serial?`<div><span>Serial</span><b dir="ltr">${e(router.serial)}</b></div>`:''}</div>${router.serial_verified?`<div class="dashboard-alert success">تم التحقق من الجهاز.</div>`:verified?`<button class="button primary" data-action="verify" ${A.busy?'disabled':''}>إنشاء كود التحقق</button>`:`<p>أكد بريدك أولًا لتفعيل الخطوة.</p>`}${A.verifyScript?scriptBlock('verify',A.verifyScript):''}<div class="how-to"><h3>خطوات التحقق</h3><ol><li>أنشئ كود التحقق من هذا القسم.</li><li>انسخه كاملًا، ونفذه على جهاز MikroTik الخاص بك.</li><li>ارجع إلى الحساب واضغط تحديث لقراءة نتيجة التحقق من السيرفر.</li></ol></div></div>`;
case 'access':return `<div class="dash-intro"><h2>عناوين الوصول وخيارات الاتصال.</h2><p>تظهر فقط المعلومات التي يعيدها السيرفر لحسابك. قد تتوقف إمكانية الوصول عندما تكون الخدمة غير مفعّلة.</p></div>${router.provisioned?`<div class="dash-panel"><div class="dash-panel-head"><h2>بيانات الاتصال</h2>${statusPill(router.remote_access_enabled?'active':'suspended')}</div>${router.remote_access_host?`<div class="copy-row"><div><span>Remote Host</span><strong dir="ltr">${e(router.remote_access_host)}</strong></div><button data-copy="host" class="inline-action">نسخ</button></div>`:''}${router.remote_alias||router.device_portal?.username?`<div class="copy-row"><div><span>حساب OnStar Cloud</span><strong dir="ltr">${e(router.device_portal?.username||router.remote_alias)}</strong></div><button data-copy="alias" class="inline-action">نسخ</button></div>`:''}${(router.access_endpoints||[]).length?`<div class="endpoint-list">${router.access_endpoints.map((ep,i)=>`<div class="endpoint"><div><span>${e(ep.label||ep.service)}</span><b dir="ltr">${e(ep.address||'')}</b>${ep.url?`<small dir="ltr">${e(ep.url)}</small>`:''}</div><div><button class="small-button" data-copy="ep-${i}">نسخ</button>${router.remote_access_enabled&&safeExternal(ep.url)?`<a href="${e(safeExternal(ep.url))}" target="_blank" rel="noopener noreferrer" class="small-button">فتح ↗</a>`:''}</div></div>`).join('')}</div>`:blank('لا توجد منافذ وصول مخصصة بعد')}${!router.remote_access_enabled?`<div class="dashboard-alert">خدمة الوصول غير مفعّلة حاليًا. لا يعني وجود عناوين محفوظة أنها تعمل الآن.</div>`:''}</div><div class="dash-panel"><h2>كود إعداد الاتصال</h2><p>كود الإعداد خاص بحسابك، ويُعرض عند طلبه فقط.</p><button class="button primary" data-action="setup" ${A.busy?'disabled':''}>جلب كود الاتصال</button>${A.script?scriptBlock('setup',A.script):''}</div>${A.ports?portForm():''}`:`<div class="dash-panel">${blank('لم يتم تجهيز الاتصال بعد','تظهر معلومات الاتصال بعد موافقة الإدارة وتجهيز الخدمة.')}</div>`}`;
case 'devices':{const dp=router.device_portal;let url=null;if(dp?.url){try{const parsed=new URL(dp.url);if(['https:','http:'].includes(parsed.protocol)){parsed.searchParams.set('username',dp.username||'');url=parsed.href}}catch{}}return `<div class="dash-intro"><h2>لوحة أجهزتك، بتصريح حسابك.</h2><p>لوحة الأجهزة خدمة منفصلة عن حساب الاشتراك. قد تتطلب تسجيل الدخول بأوراق اعتماد مخصصة لها.</p></div><div class="dash-panel">${dp?`<div class="info-rows"><div><span>اسم مستخدم اللوحة</span><b dir="ltr">${e(dp.username||'')}</b></div><div><span>الحد المسموح للأجهزة</span><b>${e(dp.max_devices??'حسب الصلاحيات')}</b></div></div>${url?`<a class="button primary" href="${e(url)}" target="_blank" rel="noopener noreferrer">فتح لوحة الأجهزة ↗</a>`:'<p>رابط لوحة الأجهزة غير متاح حاليًا.</p>'}<div class="how-to"><h3>الدخول باستخدام Passkey</h3><p>إذا كانت لوحة الأجهزة تدعم Passkey لحسابك، سجّل الدخول بالطريقة المعتادة أول مرة، ثم أضف مفتاح مرور من قسم أمان اللوحة. بعدها يمكنك استخدام بصمة الجهاز أو وسيلة القفل المدعومة.</p></div>`:blank('لم يتم تخصيص لوحة أجهزة لحسابك','يظهر رابط الإدارة عند إتاحته من الخدمة.')}</div>`}
case 'settings':return `<div class="dash-intro"><h2>أمان حسابك، أولًا.</h2><p>معلومات حسابك الأساسية وحالة التحقق، مع الحفاظ على سرية بيانات الدخول.</p></div><div class="dash-panel"><div class="info-rows"><div><span>الاسم</span><b>${e(c.full_name||'—')}</b></div><div><span>الشبكة</span><b>${e(c.network_name||'—')}</b></div><div><span>البريد</span><b dir="ltr">${e(c.email||'—')}</b></div><div><span>التحقق من البريد</span><b>${verified?'مؤكد':'غير مؤكد'}</b></div></div><div class="button-row"><a class="button dark-outline" data-link href="/forgot-password">استعادة كلمة المرور ↗</a><button class="button dark-outline" data-action="logout">تسجيل الخروج</button></div></div>`;
default:return ''}}
const itemRows=(list,render)=>list.length?`<div class="data-rows">${list.map(x=>`<div class="data-row">${render(x)}</div>`).join('')}</div>`:blank('لا توجد سجلات بعد');
const scriptBlock=(type,value)=>`<div class="secret-script"><div><b>الكود الصادر من السيرفر</b><button class="inline-action" data-copy="${type}">نسخ الكود</button></div><textarea dir="ltr" readonly aria-label="كود إعداد صادر من السيرفر">${e(value)}</textarea><p>احتفظ بالكود داخل حسابك، ولا تنشره أو تشاركه.</p></div>`;
function portForm(){const sv=A.ports.services||{};return `<div class="dash-panel"><div class="dash-panel-head"><h2>منافذ MikroTik الداخلية</h2><span>التعديل حسب إعدادات جهازك</span></div><p>إذا كانت المنافذ الداخلية تختلف عن القيم الافتراضية، أدخل المنافذ الفعلية ثم احفظها. المنافذ العامة لا تتغير.</p><form id="ports-form"><div class="form-grid">${['api','ftp','ssh'].map(key=>`<label class="field"><span>${key.toUpperCase()} الداخلي</span><input required min="1" max="65535" type="number" name="${key}_port" value="${e(sv[key]?.internal_port??'')}" ${sv[key]?.enabled===false?'disabled':''}/><small>الخارجي: ${e(sv[key]?.public_port||'غير مفعّل')}</small></label>`).join('')}</div><button class="button primary" ${A.busy?'disabled':''}>حفظ ومزامنة المنافذ</button></form></div>`}
export function accountShell(){title('لوحة المشترك');return `<section class="dashboard-page"><div id="account-root"><div class="dashboard-loader" role="status"><span class="loading-spin"></span>جارٍ تحميل الحساب من السيرفر...</div></div></section>`}
function renderAccount(){const r=document.getElementById('account-root');if(r)r.innerHTML=accountView()}
async function perform(name,fn,success){A.busy=name;A.error='';A.message='';renderAccount();try{await fn();if(success)A.message=success;await refreshAccount(false);if(success)A.message=success;renderAccount();notify(success||'تم تنفيذ العملية')}catch(err){A.error=err.message;renderAccount();notify(A.error,'error')}finally{A.busy='';renderAccount()}}
export function accountEvents(){const root=document.getElementById('account-root');if(!root)return;
root.addEventListener('click',async(ev)=>{const tab=ev.target.closest('[data-tab]');if(tab){A.tab=tab.dataset.tab;A.error='';A.message='';renderAccount();root.scrollIntoView({behavior:'smooth',block:'start'});return}
const copyButton=ev.target.closest('[data-copy]');if(copyButton){const r=A.data?.router||{};const k=copyButton.dataset.copy;const content=k==='verify'?A.verifyScript:k==='setup'?A.script:k==='host'?r.remote_access_host:k==='alias'?(r.device_portal?.username||r.remote_alias):k==='paymentAccount'?A.config?.payment?.account_number:k.startsWith('ep-')?(r.access_endpoints||[])[Number(k.slice(3))]?.url||(r.access_endpoints||[])[Number(k.slice(3))]?.address:'';try{await copy(content);notify('تم النسخ')}catch{notify('تعذّر النسخ، حدد النص وانسخه يدويًا','error')}return}
const btn=ev.target.closest('[data-action]');if(!btn||A.busy)return;const a=btn.dataset.action; if(a==='refresh'){await refreshAccount();return} if(a==='logout'){A.busy='logout';try{await post('/logout',{});A.data=null;A.ports=null;A.script='';A.verifyScript='';state.me=null;state.meChecked=true;document.dispatchEvent(new CustomEvent('onstar:navigate',{detail:'/'}))}catch(err){A.error=err.message;A.busy='';renderAccount()}return}
if(a==='resend'){await perform(a,async()=>{const d=await post('/email/resend',{email:A.data.customer.email});if(d.email_sent===false)throw new Error('تعذّر إرسال البريد حاليًا')},'تم طلب رمز جديد إلى بريدك.');return}
if(a==='order'){const p=A.plans.find(x=>String(x.id)===btn.dataset.id);if(!p||!confirm(`إنشاء طلب وبند مالي للباقة «${p.name}»؟`))return;await perform(a,async()=>{const r=await post('/order',{plan_id:p.id,notes:''});A.message=r.invoice_no?`تم إنشاء الفاتورة ${r.invoice_no}`:'تم إنشاء الطلب والفاتورة'},'تم إنشاء الطلب والفاتورة. تابع بيانات الدفع.');return}
if(a==='trial'){if(!confirm('إرسال طلب التجربة إلى الإدارة للمراجعة؟'))return;await perform(a,()=>post('/trial/request',{}),'تم إرسال طلب التجربة، ولا تبدأ إلا بعد موافقة الإدارة.');return}
if(a==='verify'){await perform(a,async()=>{const r=await post('/router/verification-token',{});A.verifyScript=r.script||''},'تم تجهيز كود التحقق. انسخه ونفذه في MikroTik.');return}
if(a==='setup'){await perform(a,async()=>{const r=await get('/router/setup-script');A.script=r.script||''},'تم جلب كود إعداد الاتصال.');return}
});
root.addEventListener('submit',async ev=>{const f=ev.target;if(f.id==='payment-form'){ev.preventDefault();if(A.busy)return;const fd=new FormData(f);const receipt=fd.get('receipt');if(receipt instanceof File&&!receipt.size)fd.delete('receipt');if(!fd.get('invoice_id'))fd.delete('invoice_id');const amount=Number(fd.get('amount'));if(!Number.isFinite(amount)||amount<=0){notify('أدخل مبلغًا صحيحًا','error');return}if(!confirm('إرسال الإثبات للمراجعة؟ لن يتم تفعيل الخدمة حتى اعتماد الإدارة.'))return;await perform('payment',()=>api('/payment-confirmations',{method:'POST',body:fd}),'تم إرسال إثبات الدفع للمراجعة.');}
if(f.id==='ports-form'){ev.preventDefault();if(A.busy)return;const values=formValues(f);const sv=A.ports?.services||{};const keys=['api','ftp','ssh'];const b={};for(const key of keys)b[`${key}_port`]=values[`${key}_port`]?Number(values[`${key}_port`]):Number(sv[key]?.internal_port);if(!Object.values(b).every(n=>Number.isInteger(n)&&n>=1&&n<=65535)||new Set(Object.values(b)).size!==3){notify('يجب أن تكون المنافذ صحيحة ومختلفة بين API وFTP وSSH','error');return}if(!confirm('هل تريد حفظ المنافذ الداخلية وإعادة مزامنتها؟'))return;await perform('ports',()=>put('/router/connection-ports',b),'تم إرسال تعديل المنافذ إلى السيرفر واعتماد النتيجة.');}
});}
